{"security_risk":"LOW","summary":"Create erasure service","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","file_text":"import { pool, transaction } from '../../../packages/database/src/pool.js';
import {
  ErasureRepository,
  ErasureRequestConflictError,
  type ErasureRequestRow,
} from './erasure-repository.js';

const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9._:-]{8,200}$/;

export class IdempotencyKeyInvalidError extends Error {}

export interface ErasureRequestResponse {
  id: string;
  merchantId: string;
  customerId: string;
  status: ErasureRequestRow['status'];
  attempts: number;
  lastError: string | null;
  createdAt: string;
  updatedAt: string;
  startedAt: string | null;
  completedAt: string | null;
}

function serialize(row: ErasureRequestRow): ErasureRequestResponse {
  return {
    id: row.id,
    merchantId: row.merchant_id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    lastError: row.last_error,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    startedAt: row.started_at ? row.started_at.toISOString() : null,
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
  };
}

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  async create(merchantId: string, customerId: string, rawKey: string): Promise<ErasureRequestResponse> {
    const idempotencyKey = this.normalizeKey(rawKey);
    const customer = await this.repository.customerExists(merchantId, customerId);
    if (!customer) {
      throw Object.assign(new Error('customer not found'), { statusCode: 404 });
    }

    const existingForCustomer = await this.repository.findActiveForCustomer(merchantId, customerId);
    if (existingForCustomer) return serialize(existingForCustomer);

    const existingForKey = await this.repository.findByIdempotencyKey(merchantId, idempotencyKey);
    if (existingForKey) {
      if (existingForKey.customer_id !== customerId) {
        throw new ErasureRequestConflictError(existingForKey);
      }
      return serialize(existingForKey);
    }

    try {
      const created = await transaction(async (client) => {
        const rac = await client.query<{ locked: boolean }>(
          `SELECT pg_try_advisory_xact_lock(hashtext($1)) AS locked`,
          [`erasure-customer:${merchantId}:${customerId}`],
        );
        if (!rac.rows[0]?.locked) {
          throw Object.assign(new Error('customer is currently being processed'), { statusCode: 409 });
        }
        const duplicate = await client.query<ErasureRequestRow>(
          `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 LIMIT 1`,
          [merchantId, customerId],
        );
        if (duplicate.rows[0]) return duplicate.rows[0];
        return await this.repository.create(client, {
          merchantId, customerId, idempotencyKey, requestedEmail: customer.email,
        });
      });
      return serialize(created);
    } catch (error) {
      if (error instanceof Error && 'code' in error && (error as { code?: string }).code === '23505') {
        const refreshed = await this.repository.findByIdempotencyKey(merchantId, idempotencyKey);
        if (refreshed) {
          if (refreshed.customer_id !== customerId) {
            throw new ErasureRequestConflictError(refreshed);
          }
          return serialize(refreshed);
        }
        const byCustomer = await this.repository.findActiveForCustomer(merchantId, customerId);
        if (byCustomer) return serialize(byCustomer);
      }
      throw error;
    }
  }

  async findForMerchant(merchantId: string, requestId: string): Promise<ErasureRequestResponse | undefined> {
    const row = await this.repository.findByIdForMerchant(merchantId, requestId);
    return row ? serialize(row) : undefined;
  }

  private normalizeKey(rawKey: string): string {
    const key = rawKey.trim();
    if (!IDEMPOTENCY_KEY_PATTERN.test(key)) {
      throw new IdempotencyKeyInvalidError('Idempotency-Key must be 8-200 chars from [A-Za-z0-9._:-]');
    }
    return key;
  }
}"}

