export async function erasureRoutes(app: FastifyInstance): Promise<void> {
  const service = new ErasureService();
  const repository = new ErasureRepository();

  app.post('/v1/customers/:customerId/erasure-requests', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { customerId } = z.object({ customerId: z.string().uuid() }).parse(request.params);
    const idempotencyKey = request.headers['idempotency-key'];
    if (typeof idempotencyKey !== 'string' || idempotencyKey.length === 0) {
      return reply.code(400).send({ error: 'idempotency_key_required' });
    }
    try {
      const result = await service.create(principal.merchantId, customerId, idempotencyKey);
      return reply.code(202).send(result);
    } catch (error) {
      if (error instanceof IdempotencyKeyInvalidError) {
        return reply.code(400).send({ error: 'idempotency_key_invalid' });
      }
      if (error instanceof ErasureRequestConflictError) {
        return reply.code(409).send({ error: 'idempotency_key_reused_for_other_customer', requestId: error.existing.id });
      }
      const status = (error as { statusCode?: number }).statusCode;
      if (status === 404) return reply.code(404).send({ error: 'customer_not_found' });
      if (status === 409) return reply.code(409).send({ error: 'erasure_request_in_progress' });
      throw error;
    }
  });

  app.get('/v1/erasure-requests/:requestId', async (request, reply) => {
    const principal = await authenticate(request, 'privacy:erase');
    const { requestId } = z.object({ requestId: z.string().uuid() }).parse(request.params);
    const existing = await service.findForMerchant(principal.merchantId, requestId)
      ?? (await repository.findByIdForMerchant(principal.merchantId, requestId) ? undefined : undefined);
    if (!existing) return reply.code(404).send({ error: 'erasure_request_not_found' });
    return existing;
  });
}"}

