{"security_risk":"LOW","summary":"Create privacy worker repository","command":"create","path":"/workspace/source/apps/privacy-worker/src/repository.ts","file_text":"import type pg from 'pg';
import { pool, transaction } from '../../../packages/database/src/pool.js';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  idempotency_key: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  last_error: string | null;
  requested_email: string | null;
  created_at: Date;
  updated_at: Date;
  started_at: Date | null;
  completed_at: Date | null;
}

export class ErasureRepository {
  async claim(workerId: string): Promise<ErasureRequestRow | undefined> {
    return await transaction(async (client) => {
      const result = await client.query<ErasureRequestRow>(
        `SELECT * FROM customers.erasure_requests
         WHERE status='pending'
         ORDER BY created_at
         FOR UPDATE SKIP LOCKED LIMIT 1`,
      );
      const row = result.rows[0];
      if (!row) return undefined;
      const updated = await client.query<ErasureRequestRow>(
        `UPDATE customers.erasure_requests
         SET status='processing', attempts=attempts+1, started_at=COALESCE(started_at,now()), updated_at=now()
         WHERE id=$1
         RETURNING *`,
        [row.id],
      );
      if (!updated.rowCount) return undefined;
      await client.query(
        `INSERT INTO operations.job_attempts(job_id,worker_id,status,started_at)
         VALUES($1,$2,'processing',now())`,
        [row.id, workerId],
      );
      return updated.rows[0];
    });
  }

  async complete(requestId: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='completed', last_error=NULL, completed_at=now(), updated_at=now(),
           requested_email=NULL
       WHERE id=$1`,
      [requestId],
    );
  }

  async fail(requestId: string, errorCode: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed', last_error=$2, updated_at=now()
       WHERE id=$1`,
      [requestId, errorCode.slice(0, 200)],
    );
  }

  async resetForRetry(requestId: string, errorCode: string, baseDelaySeconds: number): Promise<Date> {
    const availableAt = new Date(Date.now() + Math.max(1, baseDelaySeconds) * 1000);
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='pending', last_error=$2, updated_at=now(),
           started_at=NULL
       WHERE id=$1`,
      [requestId, errorCode.slice(0, 200)],
    );
    return availableAt;
  }
}"}

{"security_risk":"LOW","summary":"Create privacy worker service","command":"create","path":"/workspace/source/apps/privacy-worker/src/service.ts","file_text":"import type pg from 'pg';
import { Redis } from 'ioredis';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { config } from '../../../packages/config/src/index.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import type { ErasureRequestRow } from './repository.js';

const REDACTED_PLACEHOLDER_EMAIL = 'redacted@example.invalid';
const REDACTED_PLACEHOLDER_NAME = 'redacted';
const REDACTED_PLACEHOLDER_PHONE = null;

interface CleanupSummary {
  addressesRemoved: number;
  contactsRemoved: number;
  paymentMethodsRemoved: number;
  supportTicketsRemoved: number;
  notificationsRemoved: number;
  notificationsAnonymized: number;
  emailDeliveriesRemoved: number;
  emailDeliveriesAnonymized: number;
  analyticsEventsRemoved: number;
  notificationPreferencesRemoved: number;
  customerImportsRemoved: number;
  documentsRemoved: number;
  paymentIntentsAnonymized: number;
  refundsAnonymized: number;
  invoicesAnonymized: number;
  providerCustomerMappingsRemoved: number;
  sandboxCustomersRemoved: number;
  searchDocumentsRemoved: number;
  redisKeysRemoved: number;
  mailpitMessagesRemoved: number;
}

const EMPTY_SUMMARY: CleanupSummary = {
  addressesRemoved: 0, contactsRemoved: 0, paymentMethodsRemoved: 0, supportTicketsRemoved: 0,
  notificationsRemoved: 0, notificationsAnonymized: 0, emailDeliveriesRemoved: 0, emailDeliveriesAnonymized: 0,
  analyticsEventsRemoved: 0, notificationPreferencesRemoved: 0, customerImportsRemoved: 0, documentsRemoved: 0,
  paymentIntentsAnonymized: 0, refundsAnonymized: 0, invoicesAnonymized: 0,
  providerCustomerMappingsRemoved: 0, sandboxCustomersRemoved: 0,
  searchDocumentsRemoved: 0, redisKeysRemoved: 0, mailpitMessagesRemoved: 0,
};

function isStableErrorCode(code: string): boolean {
  return /^[a-z][a-z0-9_]{2,63}$/.test(code);
}

export class ErasureCleanupError extends Error {
  constructor(readonly code: string) {
    super(code);
    if (!isStableErrorCode(code)) throw new Error('error code must be a stable identifier');
  }
}

export class ErasureCleanupService {
  private readonly redis: Redis;

  constructor(redis = new Redis(config().REDIS_URL)) {
    this.redis = redis;
  }

  async execute(request: ErasureRequestRow): Promise<CleanupSummary> {
    const summary: CleanupSummary = { ...EMPTY_SUMMARY };
    const merchantId = request.merchant_id;
    const customerId = request.customer_id;
    const originalEmail = request.requested_email;

    await transaction(async (client) => {
      const customerExists = await this.anonymizeCustomer(client, merchantId, customerId);
      if (!customerExists) throw new ErasureCleanupError('customer_not_found');

      summary.addressesRemoved = await this.deleteAddresses(client, merchantId, customerId);
      summary.contactsRemoved = await this.deleteContacts(client, merchantId, customerId);
      summary.paymentMethodsRemoved = await this.deletePaymentMethods(client, merchantId, customerId);

      const ticketIds = await this.collectTicketIds(client, merchantId, customerId);
      summary.supportTicketsRemoved = ticketIds.length > 0
        ? await this.deleteSupportTickets(client, ticketIds)
        : 0;

      summary.notificationPreferencesRemoved = await this.deleteNotificationPreferences(client, merchantId, customerId);
      summary.notificationsRemoved = await this.deleteNotifications(client, merchantId, customerId);
      summary.emailDeliveriesRemoved = await this.deleteEmailDeliveries(client, merchantId, customerId);
      summary.analyticsEventsRemoved = await this.deleteAnalyticsEvents(client, merchantId, customerId);

      summary.paymentIntentsAnonymized = await this.anonymizePaymentIntents(client, merchantId, customerId);
      summary.refundsAnonymized = await this.anonymizeRefunds(client, merchantId, customerId);
      summary.invoicesAnonymized = await this.anonymizeInvoices(client, merchantId, customerId);

      summary.customerImportsRemoved = await this.deleteCustomerImports(client, merchantId, customerId);
      summary.documentsRemoved = await this.deleteFinancialDocumentsForCustomer(client, merchantId, customerId);

      summary.providerCustomerMappingsRemoved = await this.deleteProviderCustomerMappings(client, merchantId, customerId);
      summary.sandboxCustomersRemoved = await this.deleteSandboxCustomers(client, merchantId, customerId);

      summary.mailpitMessagesRemoved = await this.eraseRequestedEmail(request.id, originalEmail);
    });

    summary.searchDocumentsRemoved = await this.removeFromSearchIndex(merchantId, customerId);
    summary.redisKeysRemoved = await this.removeFromRedisCache(merchantId, customerId);

    return summary;
  }

  private async anonymizeCustomer(client: pg.PoolClient, merchantId: string, customerId: string): Promise<boolean> {
    const result = await client.query(
      `UPDATE customers.customers
       SET email=$3,
           name=$4,
           phone=$5,
           external_reference=COALESCE(NULLIF(external_reference,''),$6),
           metadata='{}'::jsonb,
           status='erased',
           erased_at=COALESCE(erased_at,now()),
           version=version+1,
           updated_at=now()
       WHERE merchant_id=$1 AND id=$2
       RETURNING id`,
      [
        merchantId, customerId,
        REDACTED_PLACEHOLDER_EMAIL, REDACTED_PLACEHOLDER_NAME, REDACTED_PLACEHOLDER_PHONE,
        `erased-${customerId}`,
      ],
    );
    return result.rowCount === 1;
  }

  private async deleteAddresses(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const result = await client.query(
      `DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rowCount ?? 0;
  }

  private async deleteContacts(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const result = await client.query(
      `DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rowCount ?? 0;
  }

  private async deletePaymentMethods(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const result = await client.query(
      `DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rowCount ?? 0;
  }

  private async collectTicketIds(client: pg.PoolClient, merchantId: string, customerId: string): Promise<string[]> {
    const result = await client.query<{ id: string }>(
      `SELECT t.id FROM customers.support_tickets t
       JOIN customers.support_participants p ON p.ticket_id=t.id
       WHERE t.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows.map((row) => row.id);
  }

  private async deleteSupportTickets(client: pg.PoolClient, ticketIds: string[]): Promise<number> {
    if (ticketIds.length === 0) return 0;
    const messages = await client.query(
      `DELETE FROM customers.support_messages WHERE ticket_id = ANY($1::uuid[])`,
      [ticketIds],
    );
    const participants = await client.query(
      `DELETE FROM customers.support_participants WHERE ticket_id = ANY($1::uuid[])`,
      [ticketIds],
    );
    const tickets = await client.query(
      `DELETE FROM customers.support_tickets WHERE id = ANY($1::uuid[])`,
      [ticketIds],
    );
    logger.debug({ messages: messages.rowCount, participants: participants.rowCount, tickets: tickets.rowCount }, 'support tickets deleted');
    return tickets.rowCount ?? 0;
  }

  private async deleteNotificationPreferences(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const result = await client.query(
      `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rowCount ?? 0;
  }

  private async deleteNotifications(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const result = await client.query(
      `DELETE FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rowCount ?? 0;
  }

  private async deleteEmailDeliveries(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const result = await client.query(
      `DELETE FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rowCount ?? 0;
  }

  private async deleteAnalyticsEvents(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const result = await client.query(
      `DELETE FROM operations.analytics_events WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rowCount ?? 0;
  }

  private async anonymizePaymentIntents(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const result = await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=jsonb_build_object(
         'status','erased',
         'customerId', id::text
       )
       WHERE merchant_id=$1 AND customer_id=$2
         AND customer_snapshot ? 'email'`,
      [merchantId, customerId],
    );
    return result.rowCount ?? 0;
  }

  private async anonymizeRefunds(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const result = await client.query(
      `UPDATE payments.refunds
       SET customer_email=$3
       WHERE merchant_id=$1 AND payment_intent_id IN (
         SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2
       )
       AND customer_email IS NOT NULL`,
      [merchantId, customerId, REDACTED_PLACEHOLDER_EMAIL],
    );
    return result.rowCount ?? 0;
  }

  private async anonymizeInvoices(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const result = await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot=jsonb_build_object('status','erased')
       WHERE merchant_id=$1 AND customer_id=$2
         AND billing_snapshot ? 'email'`,
      [merchantId, customerId],
    );
    return result.rowCount ?? 0;
  }

  private async deleteCustomerImports(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const imports = await client.query<{ id: string; object_key: string }>(
      `SELECT id, object_key FROM customers.customer_imports WHERE merchant_id=$1 AND object_key LIKE $2`,
      [merchantId, `${merchantId}/imports/%`],
    );
    if (imports.rows.length === 0) return 0;
    for (const row of imports.rows) {
      await this.removeObject(row.object_key);
    }
    const manifestDelete = await client.query(
      `DELETE FROM operations.document_manifests
       WHERE merchant_id=$1 AND document_type='customer_import'
         AND object_key = ANY($2::text[])`,
      [merchantId, imports.rows.map((row) => row.object_key)],
    );
    const importsDelete = await client.query(
      `DELETE FROM customers.customer_imports WHERE id = ANY($1::uuid[])`,
      [imports.rows.map((row) => row.id)],
    );
    return importsDelete.rowCount ?? 0;
  }

  private async deleteFinancialDocumentsForCustomer(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const documents = await client.query<{ object_key: string; document_type: string }>(
      `SELECT object_key, document_type FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    let removed = 0;
    for (const row of documents.rows) {
      if (row.document_type === 'customer_import') continue;
      if (row.document_type === 'receipt') {
        await this.overwriteReceipt(row.object_key, customerId);
      } else if (row.document_type === 'invoice') {
        await this.overwriteInvoice(row.object_key, customerId);
      } else {
        await this.removeObject(row.object_key);
      }
      removed += 1;
    }
    await client.query(
      `UPDATE operations.document_manifests SET customer_id=NULL WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return removed;
  }

  private async overwriteReceipt(objectKey: string, customerId: string): Promise<void> {
    const body = JSON.stringify({
      receiptNumber: customerId,
      issuedAt: new Date(0).toISOString(),
      customer: { status: 'erased' },
      amount: null,
      currency: 'USD',
      redacted: true,
    });
    try {
      await objectStore.putObject(DOCUMENT_BUCKET, objectKey, body, Buffer.byteLength(body),
        { 'Content-Type': 'application/json' });
    } catch (error) {
      logger.warn({ error, objectKey }, 'failed to overwrite receipt; falling back to delete');
      await this.removeObject(objectKey);
    }
  }

  private async overwriteInvoice(objectKey: string, customerId: string): Promise<void> {
    const body = JSON.stringify({
      invoiceNumber: customerId,
      issuedAt: new Date(0).toISOString(),
      billing: { status: 'erased' },
      lines: [],
      redacted: true,
    });
    try {
      await objectStore.putObject(DOCUMENT_BUCKET, objectKey, body, Buffer.byteLength(body),
        { 'Content-Type': 'application/json' });
    } catch (error) {
      logger.warn({ error, objectKey }, 'failed to overwrite invoice; falling back to delete');
      await this.removeObject(objectKey);
    }
  }

  private async removeObject(objectKey: string): Promise<void> {
    try { await objectStore.removeObject(DOCUMENT_BUCKET, objectKey); }
    catch (error) { logger.warn({ error, objectKey }, 'failed to remove object'); }
  }

  private async deleteProviderCustomerMappings(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const mappings = await client.query<{ provider_customer_id: string }>(
      `DELETE FROM customers.provider_customer_mappings
       WHERE merchant_id=$1 AND customer_id=$2
       RETURNING provider_customer_id`,
      [merchantId, customerId],
    );
    return mappings.rowCount ?? 0;
  }

  private async deleteSandboxCustomers(client: pg.PoolClient, merchantId: string, customerId: string): Promise<number> {
    const result = await client.query(
      `DELETE FROM provider_sandbox.customers WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rowCount ?? 0;
  }

  private async removeFromSearchIndex(merchantId: string, customerId: string): Promise<number> {
    try {
      await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}`, refresh: false });
      return 1;
    } catch (error) {
      const status = (error as { statusCode?: number }).statusCode;
      if (status === 404) return 0;
      logger.warn({ error, merchantId, customerId }, 'failed to remove from search index');
      throw new ErasureCleanupError('search_index_unavailable');
    }
  }

  private async removeFromRedisCache(merchantId: string, customerId: string): Promise<number> {
    let removed = 0;
    const pattern = `merchant:${merchantId}:customer:${customerId}*`;
    let cursor = '0';
    do {
      const [next, keys] = await this.redis.scan(cursor, 'MATCH', pattern, 'COUNT', 100);
      cursor = next;
      if (keys.length > 0) {
        await this.redis.del(...keys);
        removed += keys.length;
      }
    } while (cursor !== '0');
    return removed;
  }

  private async eraseRequestedEmail(requestId: string, email: string | null): Promise<number> {
    if (!email) return 0;
    try {
      await deleteMailpitMessagesForRecipient(email);
      return 1;
    } catch (error) {
      logger.warn({ error, requestId }, 'mailpit cleanup failed; continuing');
      return 0;
    }
  }
}"}

{"security_risk":"LOW","summary":"Create privacy worker main","command":"create","path":"/workspace/source/apps/privacy-worker/src/main.ts","file_text":"import { randomUUID } from 'node:crypto';
import Fastify from 'fastify';
import { config } from '../../../packages/config/src/index.js';
import { registerErrorHandler } from '../../../packages/http/src/errors.js';
import { boundedExponentialBackoffSeconds } from '../../../packages/operations/src/retry-policy.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { ErasureRepository } from './repository.js';
import { ErasureCleanupError, ErasureCleanupService } from './service.js';

process.env.SERVICE_NAME = 'privacy-worker';
const repository = new ErasureRepository();
const cleanup = new ErasureCleanupService();
const workerId = `privacy-worker-${randomUUID()}`;

const app = Fastify({
  logger: {
    level: config().LOG_LEVEL, base: { service: 'privacy-worker' },
    redact: ['req.headers.authorization', '*.apiKey', '*.providerToken']
  }
});
registerErrorHandler(app);
app.get('/health', async () => ({ status: 'ok', service: 'privacy-worker' }));

const MAX_ATTEMPTS = 8;

async function processOne(): Promise<boolean> {
  const row = await repository.claim(workerId);
  if (!row) return false;

  try {
    const summary = await cleanup.execute(row);
    await repository.complete(row.id);
    logger.info({ requestId: row.id, customerId: row.customer_id, summary }, 'erasure completed');
  } catch (error) {
    const code = error instanceof ErasureCleanupError
      ? error.code
      : 'cleanup_failed';
    if (row.attempts >= MAX_ATTEMPTS) {
      await repository.fail(row.id, code);
      logger.error({ requestId: row.id, code, attempts: row.attempts }, 'erasure failed terminally');
    } else {
      const delay = boundedExponentialBackoffSeconds(row.attempts);
      await repository.resetForRetry(row.id, code, delay);
      logger.warn({ requestId: row.id, code, attempts: row.attempts, delaySeconds: delay },
        'erasure will retry');
    }
  }
  return true;
}

async function loop(signal: AbortSignal): Promise<void> {
  while (!signal.aborted) {
    let processed = false;
    try { processed = await processOne(); }
    catch (error) { logger.error({ error }, 'unexpected loop error'); }
    if (!processed) await new Promise((resolve) => setTimeout(resolve, 500));
  }
}

const controller = new AbortController();
void loop(controller.signal);
await app.listen({ host: '0.0.0.0', port: 3011 });
for (const signal of ['SIGTERM', 'SIGINT'] as const) process.on(signal, () => { controller.abort(); void app.close(); });"}

