{"security_risk":"LOW","summary":"Create erasure tests","command":"create","path":"/workspace/source/tests/erasure.test.ts","file_text":"import assert from 'node:assert/strict';
import test from 'node:test';
import { IdempotencyKeyInvalidError } from '../apps/customer-service/src/erasure-service.js';
import { ErasureCleanupError } from '../apps/privacy-worker/src/service.js';

test('ErasureCleanupError throws for unstable error codes', () => {
  assert.throws(() => new ErasureCleanupError('UPPERCASE'), /error code/);
  assert.throws(() => new ErasureCleanupError('1-bad-start'), /error code/);
  assert.throws(() => new ErasureCleanupError('x'), /error code/);
  assert.throws(() => new ErasureCleanupError('a'.repeat(80)), /error code/);
  assert.doesNotThrow(() => new ErasureCleanupError('customer_not_found'));
  assert.doesNotThrow(() => new ErasureCleanupError('search_index_unavailable'));
  assert.equal(new ErasureCleanupError('ok_code').code, 'ok_code');
});

test('IdempotencyKeyInvalidError conveys a validation message', () => {
  const error = new IdempotencyKeyInvalidError('Idempotency-Key must be 8-200 chars from [A-Za-z0-9._:-]');
  assert.equal(error.name, 'IdempotencyKeyInvalidError');
  assert.match(error.message, /Idempotency-Key/);
});

test('idempotency key regex accepts safe punctuation but rejects whitespace and control chars', () => {
  const valid = ['abcdefgh', 'AABBCCDD-1234', 'order_id:42', 'file.version-1', 'a'.repeat(200)];
  const invalid = ['', 'x'.repeat(7), 'x'.repeat(201), 'has space', 'bad/slash', 'bad;semicolon'];
  const re = /^[A-Za-z0-9._:-]{8,200}$/;
  for (const key of valid) assert.equal(re.test(key), true, `expected valid: ${key}`);
  for (const key of invalid) assert.equal(re.test(key), false, `expected invalid: ${key}`);
});

test('idempotency-key requires non-empty trim', () => {
  const re = /^[A-Za-z0-9._:-]{8,200}$/;
  for (const candidate of ['          ', '   x   ', '\n\n\n']) {
    assert.equal(re.test(candidate.trim()), false);
  }
});"}

